line.example:
const { Gizmo } = kcds.world;

const id = Gizmo.line(player.position, npc.position, { color: kcds.math.Color.red(), durationMs: 5000 });
Gizmo.text(npc.position, 'Target', { players: [player] });
Gizmo.clear(id);

line.exampleCs:
var id = Gizmo.Line(player.Position, npc.Position, new { color = Color.Red(), durationMs = 5000 });
Gizmo.Text(npc.Position, "Target", new { players = new[] { player } });
Gizmo.Clear(id);

clear.example:
const { Gizmo } = kcds.world;

Gizmo.clear(id, [player]); // one gizmo, for one player
Gizmo.clear(); // all gizmos
